t.script:
document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll(".tab-pane").forEach(function (pane) {
        var filter = pane.querySelector(".category-filter");
        if (!filter) return;

        var menu = filter.querySelector(".filter-menu");
        var options = filter.querySelector(".filter-options");
        if (options) {
            options.innerHTML = "";
        }
        var categories = [];
        var pairs = [];

        pane.querySelectorAll(".s_text_block").forEach(function (textBlock) {
            var next = textBlock.nextElementSibling;
            if (next && next.classList.contains("s_three_columns")) {
                var span = textBlock.querySelector(".s_allow_columns span");
                if (span) {
                    var name = span.textContent.trim();
                    next.dataset.category = name;
                    pairs.push({ text: textBlock, grid: next, name: name });
                    if (!categories.includes(name)) {
                        categories.push(name);
                    }
                }
            }
        });

        if (!categories.length) {
            filter.style.display = "none";
            return;
        }

        categories.forEach(function (name) {
            var label = document.createElement("label");
            var input = document.createElement("input");
            input.type = "checkbox";
            input.value = name;
            input.checked = true;
            label.appendChild(input);
            label.appendChild(document.createTextNode(" " + name));
            options.appendChild(label);
        });

        function update() {
            var selected = Array.from(menu.querySelectorAll("input[type=checkbox]"))
                .filter(function (c) { return c.checked; })
                .map(function (c) { return c.value; });

            pairs.forEach(function (pair) {
                var show = selected.includes(pair.name);
                pair.text.style.display = show ? "" : "none";
                pair.grid.style.display = show ? "" : "none";
            });
        }

        menu.addEventListener("change", update);

        filter.querySelector(".filter-reset").addEventListener("click", function (e) {
            e.preventDefault();
            menu.querySelectorAll("input[type=checkbox]").forEach(function (c) { c.checked = true; });
            update();
        });

        filter.querySelector(".filter-toggle").addEventListener("click", function (e) {
            e.preventDefault();
            menu.classList.toggle("d-none");
            var arrow = filter.querySelector(".filter-arrow");
            if (arrow) {
                arrow.style.transform = menu.classList.contains("d-none") ? "" : "rotate(180deg)";
            }
        });

        update();
    });
});
